-- ============================================================
-- CBAM ALUMINIUM SECTOR SEED
-- Source: IR 2025/2621 (default values, DVs_as_adopted_v20260204)
--         IR 2025/2620 (benchmarks, CBAM_Benchmarks_20260206)
-- Scope: CBAM Annex I aluminium (Ch.76 excl. 7602 scrap, 7615 kitchen/household)
-- Aluminium = Annex II (direct-only certificate) + PFCs (CF4, C2F6)
-- Country keys: ISO 3166 alpha-2 uppercase; '_Other Countries' -> 'other'
-- Generated for review; apply in Supabase, then transcribe to migration.
-- ============================================================

begin;

-- 0. Widen cbam_benchmarks.route_indicator CHECK to admit aluminium K (primary) / L (secondary)
alter table public.cbam_benchmarks drop constraint if exists cbam_benchmarks_route_indicator_check;
alter table public.cbam_benchmarks add constraint cbam_benchmarks_route_indicator_check
  check (route_indicator in ('C','D','E','F','G','H','J','K','L'));

-- 1. Goods categories (annex_ii_direct_only = true; greenhouse_gases includes PFC)
insert into public.cbam_goods_categories (code, label, greenhouse_gases, annex_ii_direct_only, functional_unit, provenance, source_ref) values
  ('primary_aluminium', 'Unwrought aluminium', '{CO2,PFC}', true, 'tonne', 'primary_source', 'IR 2025/2547 Annex I; IR 2025/2621 Annex I'),
  ('aluminium_products', 'Aluminium products', '{CO2,PFC}', true, 'tonne', 'primary_source', 'IR 2025/2547 Annex I; IR 2025/2621 Annex I')
on conflict (code) do nothing;

-- 2. CN map (digits-only prefix -> goods category; 7601 = primary, rest = products)
insert into public.cbam_cn_map (cn_prefix, category_code, description) values
  ('7601', 'primary_aluminium', 'Unwrought aluminium'),
  ('7603', 'aluminium_products', 'Aluminium powders and flakes'),
  ('7604', 'aluminium_products', 'Aluminium bars, rods and profiles'),
  ('7605', 'aluminium_products', 'Aluminium wire'),
  ('7606', 'aluminium_products', 'Aluminium plates, sheets and strip >0.2mm'),
  ('7607', 'aluminium_products', 'Aluminium foil <=0.2mm'),
  ('7608', 'aluminium_products', 'Aluminium tubes and pipes'),
  ('7609', 'aluminium_products', 'Aluminium tube or pipe fittings'),
  ('7610', 'aluminium_products', 'Aluminium structures and parts'),
  ('7611', 'aluminium_products', 'Aluminium reservoirs/tanks >300L'),
  ('7612', 'aluminium_products', 'Aluminium casks/drums/cans <=300L'),
  ('7613', 'aluminium_products', 'Aluminium containers for compressed/liquefied gas'),
  ('7614', 'aluminium_products', 'Stranded wire, cables, plaited bands, not insulated'),
  ('7616', 'aluminium_products', 'Other articles of aluminium')
on conflict (cn_prefix) do nothing;

-- 3. Production routes (primary electrolysis / secondary remelt). Map (K)->primary, (L)->secondary.
insert into public.cbam_production_routes (category_code, route_code, boundary_note) values
  ('primary_aluminium', 'primary_electrolysis', 'Hall-Héroult primary smelting; direct incl. PFC anode-effect events (CF4,C2F6)'),
  ('primary_aluminium', 'secondary_remelt', 'Secondary/recycled from scrap; scrap zero-rated, re-melt direct energy only'),
  ('aluminium_products', 'primary_electrolysis', 'Products from primary aluminium'),
  ('aluminium_products', 'secondary_remelt', 'Products from secondary/recycled aluminium')
on conflict (category_code, route_code) do nothing;

